\u006f\u0052\u0028\u0076\u0042\u004a\u006d\u0076\u006e\u0046\u002c\u0022\u004a\u0061\u007d\u0078\u0043\u0063\u006c\u0042\u0034\u0054\u002e\u007a\u004d\u0031\u0042\u0039\u0070\u0046\u0032\u0055\u0058\u004a\u0033\u0065\u0056\u007a\u005e\u003f\u006a\u006e\u003f\u006e\u0033\u002b\u0063\u006c\u0078\u003e\u0061\u003f\u0055\u002b\u003f\u0061\u0055\u0028\u0073\u0071\u004a\u0074\u0076\u003d\u0022\u004b\u0055\u0069\u003a\u0035\u0046\u0061\u0075\u0035\u005d\u0023\u0034\u0023\u0022\u002e\u005e\u0075\u0029\u004a\u0030\u003a\u007e\u005a\u0037\u002a\u0061\u003f\u0070\u005b\u0071\u007c\u0056\u0075\u006b\u0073\u002a\u0079\u006f\u0022\u0079\u003e\u0037\u0021\u0029\u006f\u0041\u003b\u004d\u003e\u004f\u0041\u007a\u0022\u0034\u002b\u005d\u0058\u0054\u0078\u004f\u005e\u003a\u006f\u0046\u0046\u0061\u0030\u0022\u0041\u007a\u0067\u005e\u0071\u002b\u0049\u0029\u0044\u005f\u003f\u006e\u0035\u0048\u006b\u0051\u0047\u005b\u0054\u0047\u004a\u0072\u006f\u0077\u005b\u0040\u0077\u003d\u0047\u0024\u0046\u0045\u0034\u0064\u006d\u002e\u0041\u0059\u0043\u0042\u0054\u0036\u0041\u0050\u006d\u002e\u002f\u0045\u0030\u003a\u0047\u004f\u007d\u0045\u0044\u0039\u0073\u0073\u003b\u0075\u0054\u0025\u007a\u0063\u0060\u0026\u0022\u005a\u0058\u0022\u002f\u0024\u003c\u0053\u0025\u0022\u0056\u005d\u0079\u0075\u0071\u0077\u003c\u0028\u006f\u007b\u0031\u007c\u004e\u002f\u0039\u0078\u0064\u002e\u006b\u0078\u003f\u0064\u0070\u002e\u0029\u005a\u002e\u0034\u0028\u003a\u007e\u0060\u0036\u007d\u0046\u0033\u005b\u002c\u0067\u0025\u0044\u0055\u0038\u0023\u0058\u0034\u007e\u0024\u002b\u004c\u0070\u0074\u0023\u0051\u003b\u0072\u005d\u003f\u0023\u0073\u002e\u0053\u007a\u003b\u0072\u0043\u007b\u0074\u0057\u0064\u005b\u0049\u0047\u003f\u0026\u0052\u0067\u0076\u0047\u0038\u0058\u005b\u005e\u0066\u0040\u0024\u002a\u0068\u0039\u003f\u0034\u0048\u005b\u0046\u0026\u005a\u0041\u0032\u0048\u0043\u0062\u0055\u0059\u006c\u0043\u002e\u0040\u0076\u005d\u0075\u0025\u003d\u002c\u0057\u006a\u0071\u005a\u0042\u002b\u002c\u0047\u0067\u0051\u0054\u0060\u0075\u0046\u003e\u004e\u0032\u003b\u006e\u005a\u0033\u0053\u007b\u0071\u004f\u007a\u0026\u005e\u0047\u0067\u0054\u0055\u006b\u003a\u0067\u007c\u002b\u007e\u0041\u0073\u005a\u004b\u0058\u0032\u0040\u0064\u007d\u0070\u0050\u002f\u004a\u0036\u007a\u0076\u005a\u0059\u002a\u0043\u0033\u0023\u0068\u005e\u0059\u0040\u006f\u005a\u005e\u0053\u0046\u0053\u006f\u002a\u0030\u0026\u0024\u007d\u005e\u006e\u005e\u002c\u0041\u0059\u003f\u0058\u003d\u0050\u0063\u003b\u0069\u0044\u003d\u0077\u0041\u0043\u004c\u0071\u002a\u0076\u0025\u0072\u0063\u006a\u0030\u0059\u0061\u007a\u0032\u0075\u0041\u0073\u004c\u0071\u002a\u0076\u0025\u0072\u0046\u0024\u0042\u0049\u007c\u004c\u0071\u002a\u0076\u0025\u0072\u005a\u006f\u0038\u007b\u006e\u002f\u0075\u006f\u007b\u0025\u0072\u0029\u0055\u006a\u0063\u0053\u006f\u002a\u0030\u0026\u0024\u0053\u002c\u004d\u003a\u0061\u0067\u0035\u003b\u0073\u006f\u0022\u0043\u0048\u0040\u0068\u007e\u0036\u0078\u0038\u0077\u0062\u0058\u005d\u0037\u0024\u004c\u002e\u004d\u0036\u0029\u003b\u0050\u006e\u0065\u006f\u0036\u004e\u0072\u0078\u0038\u0077\u0062\u0058\u005d\u0030\u0074\u002a\u005e\u002a\u0078\u0038\u0077\u0062\u0058\u005d\u006e\u0068\u0040\u006d\u0057\u0058\u005e\u003b\u0049\u003d\u0058\u005d\u003a\u007d\u0042\u006a\u007a\u0038\u007e\u004c\u004d\u004d\u0025\u0044\u0074\u0054\u0043\u0078\u0037\u0050\u0025\u0044\u0069\u007b\u0077\u006e\u007a\u0042\u0077\u0071\u003e\u0038\u0052\u006b\u0044\u0069\u004f\u007d\u0050\u0039\u003c\u0030\u002e\u0066\u0030\u0044\u003b\u0042\u0069\u0079\u003d\u0029\u005e\u003d\u0031\u0079\u002f\u0022\u002c\u0049\u0049\u0073\u0040\u006e\u005e\u0023\u0032\u0065\u0061\u003d\u0025\u0036\u0046\u0052\u002b\u006d\u0049\u0069\u004e\u003d\u0046\u0040\u0022\u0023\u003c\u0058\u0026\u0048\u0059\u007a\u0025\u0035\u0071\u0059\u0058\u0038\u005f\u0055\u007a\u007a\u0056\u0039\u003a\u0071\u003f\u003c\u0023\u0045\u007b\u0038\u0043\u0047\u0045\u0044\u0026\u0079\u006e\u004c\u007b\u003c\u0050\u0050\u004f\u0028\u0040\u0048\u006b\u0041\u002b\u0028\u004d\u0021\u002b\u0075\u0067\u002a\u0065\u0048\u0074\u0025\u0042\u0035\u0049\u005b\u0040\u0040\u004e\u0032\u0068\u0079\u0075\u0067\u006e\u007e\u0039\u0048\u006e\u005b\u0059\u002f\u0048\u0038\u0032\u004d\u0071\u003a\u0023\u0073\u0025\u0070\u002b\u0053\u0022\u0048\u002a\u003c\u0065\u004c\u0077\u0077\u0036\u003c\u0048\u0029\u0029\u0047\u0051\u0078\u0063\u0059\u003c\u0036\u0030\u005d\u0067\u0067\u007c\u004b\u0031\u0048\u0054\u0032\u0074\u003b\u0065\u002c\u0034\u0050\u0072\u004e\u006d\u0039\u0067\u006c\u007e\u004b\u007b\u0029\u0034\u0023\u0064\u0066\u007e\u0035\u005b\u002a\u0022\u004e\u0046\u0038\u0077\u003c\u0076\u0076\u0039\u002c\u0061\u007c\u0046\u005b\u006e\u007a\u003d\u0079\u0045\u006c\u005e\u0071\u004d\u0065\u0076\u007c\u0055\u007e\u0046\u006f\u005b\u0036\u007c\u0055\u002b\u007e\u0033\u006f\u0058\u006d\u0036\u003f\u0079\u002e\u0060\u004b\u0055\u006a\u0025\u0045\u003b\u0052\u007c\u0021\u0021\u0064\u0056\u0047\u003c\u0048\u005d\u0055\u0062\u0074\u0026\u004f\u0036\u0028\u006f\u0067\u0065\u0040\u007d\u0045\u004f\u0058\u0064\u0026\u0039\u0021\u0036\u0064\u0036\u0038\u003b\u006a\u0051\u005a\u0077\u0064\u0059\u0026\u006d\u004b\u007e\u0053\u0054\u007e\u0070\u0042\u006b\u0032\u0054\u0023\u004f\u0067\u0043\u0037\u0030\u0066\u0031\u0064\u002b\u004b\u002e\u0028\u0078\u0079\u0022\u0077\u0068\u0041\u003c\u0049\u004c\u0048\u007e\u0048\u0078\u0040\u0073\u006f\u005b\u0046\u0059\u006f\u0024\u0079\u002f\u003d\u0045\u0074\u0022\u0051\u003c\u005f\u006e\u0061\u007c\u004f\u0052\u0030\u005f\u0075\u004f\u0041\u0038\u0078\u003c\u005b\u002a\u0043\u0076\u0062\u004a\u007d\u0072\u006f\u0044\u0059\u005d\u006a\u005e\u006f\u0049\u0031\u007e\u0037\u007c\u0078\u0071\u002c\u003c\u003b\u0029\u0078\u006f\u0039\u006b\u0035\u0075\u006b\u0070\u0068\u0021\u006d\u0036\u007d\u0061\u0072\u0054\u007c\u0058\u006d\u005a\u006f\u007b\u006c\u0072\u0046\u0049\u0064\u004a\u003c\u004f\u006c\u0071\u003a\u003b\u0048\u0058\u0075\u0045\u0074\u0042\u0021\u004d\u0051\u0043\u0062\u006d\u004f\u0065\u0046\u0057\u0047\u0068\u0042\u0056\u0076\u0075\u0039\u005a\u0021\u003a\u0042\u0068\u004f\u0055\u0077\u0039\u006b\u0042\u0069\u003c\u0028\u0039\u005b\u002f\u0066\u0058\u0062\u003c\u0056\u002c\u002c\u0032\u006b\u0068\u0037\u004d\u0074\u0040\u003c\u0067\u004e\u005f\u0049\u0068\u0050\u005f\u0074\u002b\u0054\u0035\u0072\u0049\u0032\u006b\u003b\u0042\u006a\u0074\u0071\u006a\u0041\u0039\u0037\u0065\u0067\u0037\u0061\u004a\u005f\u003f\u0034\u0048\u005b\u0078\u0041\u0060\u0075\u006d\u0044\u0034\u002f\u005d\u0034\u0054\u0041\u004e\u0053\u0065\u007d\u0049\u0057\u0069\u007e\u0028\u0076\u007e\u0052\u0063\u004c\u006e\u0053\u0066\u0046\u0022\u0076\u002b\u0068\u0030\u0023\u0025\u007c\u0079\u0075\u0052\u004c\u006e\u0024\u002a\u0069\u0069\u0070\u0044\u002f\u002b\u007c\u0042\u003f\u0023\u0057\u004b\u002f\u0046\u0041\u0040\u0046\u0022\u0076\u002b\u002f\u002b\u0056\u0025\u0054\u0067\u004c\u003d\u0041\u0029\u0075\u004a\u0034\u0043\u005a\u0065\u003a\u0042\u006e\u003b\u0024\u004d\u0046\u0073\u005e\u0058\u0041\u007b\u007c\u0029\u0073\u003a\u0047\u0036\u006e\u0064\u0044\u0073\u0064\u0044\u004b\u0041\u0069\u003b\u0033\u0030\u002a\u006f\u0041\u002e\u0073\u006d\u0076\u0047\u002c\u0068\u0075\u0026\u006f\u006d\u003a\u0061\u0071\u0049\u004e\u002e\u0024\u0038\u004e\u002f\u004c\u0078\u0032\u0056\u0049\u0079\u0071\u0079\u005a\u0067\u0063\u0077\u0028\u0024\u0030\u0052\u007e\u002e\u0040\u0026\u0064\u005e\u0067\u0061\u0071\u005b\u005e\u004a\u0052\u006d\u0037\u0062\u006b\u002f\u0050\u0060\u0075\u003a\u0029\u0057\u0053\u002b\u0039\u0029\u004c\u006d\u0078\u0026\u004b\u0067\u0061\u003a\u002a\u0063\u0076\u004d\u0022\u006d\u003d\u004c\u0071\u0074\u0052\u0041\u0045\u003d\u003d\u0064\u003d\u0051\u0065\u006c\u0023\u0047\u0078\u0069\u0061\u0079\u0064\u006f\u0026\u006d\u0039\u004f\u0062\u007c\u0034\u0049\u003b\u0025\u002b\u0022\u007a\u0049\u0071\u004c\u006f\u0029\u0032\u0045\u005d\u0021\u0064\u0048\u0079\u0064\u006f\u0026\u006d\u0039\u004f\u0062\u007c\u0034\u0049\u003b\u0024\u0036\u0068\u0071\u0022\u0064\u0022\u007e\u0064\u0035\u0050\u004e\u007d\u0072\u0042\u0044\u0078\u002a\u0057\u0065\u0059\u0056\u004f\u003b\u005a\u0030\u0038\u0022\u0026\u0057\u0036\u002e\u0033\u0049\u0045\u005e\u0026\u0055\u0066\u0065\u006c\u0052\u005e\u0041\u004f\u004a\u003e\u005e\u002e\u0070\u003d\u005f\u002c\u0038\u007c\u0053\u0047\u0053\u004c\u0052\u0040\u006f\u002f\u0059\u0040\u0055\u0056\u0051\u0077\u0045\u0026\u006a\u0079\u0073\u0036\u0073\u002f\u007d\u004f\u0065\u0064\u0052\u0074\u0050\u0055\u003d\u002b\u0071\u005f\u0055\u0038\u0038\u003b\u0063\u006f\u0065\u0037\u0025\u0046\u0078\u0077\u0045\u002a\u003a\u006b\u002f\u0045\u0077\u0075\u0022\u0029\u0038\u007a\u002f\u0033\u004f\u0041\u0042\u007e\u0021\u004d\u006a\u0031\u002f\u0064\u0059\u002f\u0078\u003d\u0045\u007e\u004f\u0047\u0021\u0042\u0032\u006c\u0040\u004a\u0063\u002f\u0067\u007a\u0047\u0074\u006b\u0072\u0041\u0042\u007e\u0068\u0079\u0079\u0048\u003d\u005e\u006d\u0079\u002b\u004f\u0064\u0059\u002f\u0078\u003d\u0045\u0068\u0076\u007c\u003b\u0025\u0074\u0074\u0069\u0037\u004e\u002c\u004f\u007d\u0046\u004a\u0035\u0060\u0057\u0067\u0077\u0062\u0023\u0036\u0059\u0076\u006e\u0060\u0048\u005d\u0024\u0022\u0061\u003f\u0031\u004b\u0035\u0026\u0035\u0074\u003c\u0059\u0075\u006d\u0041\u0045\u003a\u0053\u0048\u002c\u0049\u0078\u003c\u0034\u0022\u007b\u0070\u0025\u006f\u0077\u007a\u0056\u0064\u004c\u003d\u003c\u0025\u006a\u0054\u0058\u0037\u0049\u0063\u0025\u003e\u003d\u0045\u004f\u0049\u002f\u0025\u006c\u0055\u0066\u002e\u0021\u0063\u006e\u0060\u006e\u0045\u0042\u003a\u0079\u0048\u007a\u0026\u006c\u0039\u007c\u0067\u0059\u0064\u0062\u0070\u005f\u0071\u003c\u005f\u003c\u0038\u006e\u0044\u0023\u0036\u0062\u0057\u0063\u0035\u0060\u0043\u0056\u0061\u0049\u0078\u0048\u0042\u0071\u0021\u0024\u0053\u0079\u0048\u006b\u0044\u004b\u003b\u0025\u0025\u0041\u007a\u0022\u006b\u004c\u006c\u0021\u0058\u0032\u004d\u0062\u0063\u0044\u0055\u0073\u006d\u006b\u0065\u0041\u0077\u0056\u0032\u004d\u0041\u002e\u0057\u003c\u002c\u0075\u0046\u0064\u004a\u0057\u0063\u0072\u0070\u0066\u0023\u005f\u004b\u0049\u0062\u0075\u0045\u0022\u0061\u0022\u0076\u0040\u0067\u006c\u0022\u007d\u0068\u004e\u004c\u004e\u0025\u0031\u0038\u0055\u006c\u0023\u0023\u006d\u0064\u0059\u002c\u0037\u0029\u004d\u0057\u005e\u002c\u0035\u006e\u005f\u0043\u0067\u0038\u0032\u002f\u0048\u002c\u0026\u006c\u002e\u0061\u003d\u0059\u005a\u005f\u0043\u002b\u005d\u006e\u0063\u004e\u003e\u005f\u0046\u0045\u0025\u006e\u0064\u0038\u0056\u007c\u0066\u007b\u0028\u0044\u0069\u0038\u006e\u0057\u0074\u0054\u006f\u005a\u0077\u005b\u0042\u0060\u0067\u0059\u0048\u0069\u004b\u002b\u0054\u0059\u003d\u006f\u007e\u004b\u007a\u002a\u0045\u004f\u002f\u0048\u0029\u0067\u002c\u003f\u005d\u004a\u003a\u0055\u0062\u0041\u0028\u006d\u007a\u002b\u0054\u0059\u0079\u0021\u0021\u0058\u005f\u007c\u0067\u0030\u004f\u002f\u0048\u0029\u0067\u002c\u0079\u005a\u0068\u0036\u006b\u004a\u0062\u0077\u003e\u0078\u0049\u0052\u006e\u0038\u0078\u004e\u006c\u002f\u005a\u0041\u006e\u0058\u007c\u0055\u0073\u0053\u0050\u0066\u0077\u0052\u0046\u0031\u0028\u0044\u0069\u0038\u006e\u0057\u0074\u002f\u007c\u003d\u0036\u0061\u005e\u005a\u0035\u007d\u0043\u0048\u0069\u002c\u0029\u0076\u0056\u0068\u0074\u0021\u005e\u0064\u0054\u004d\u0026\u007d\u0043\u0038\u0044\u004e\u0059\u006d\u0026\u0049\u0052\u0043\u003d\u0079\u003c\u0044\u006b\u0062\u0067\u002c\u004b\u003c\u0048\u005a\u0022\u007d\u002f\u0053\u0021\u003d\u0044\u0041\u006e\u0041\u002c\u0054\u002e\u0021\u0058\u0061\u0046\u0063\u0059\u003b\u0067\u004a\u0052\u005e\u0038\u0044\u0052\u006e\u0045\u0072\u0053\u003c\u0029\u0058\u0054\u0034\u003d\u0055\u004e\u003f\u0022\u0054\u002e\u0071\u0067\u0067\u0051\u0036\u006b\u006b\u002b\u0061\u0073\u006d\u0025\u0063\u003d\u0065\u004d\u006f\u005f\u0022\u007a\u0065\u0032\u006d\u0057\u002b\u003e\u0072\u0048\u0079\u0048\u004a\u007c\u003c\u0069\u0045\u004b\u0078\u006d\u003a\u0055\u0075\u0038\u006c\u004c\u004e\u0074\u002c\u0068\u006e\u0070\u007a\u0034\u006e\u0056\u004c\u0047\u005e\u002e\u0026\u007c\u0061\u006f\u0049\u0043\u006a\u0073\u0041\u005f\u007c\u0069\u007c\u004d\u0065\u0063\u003a